"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[5611],{5611:a=>{a.exports=JSON.parse('{"meta":{"title":"Bantuan & FAQ - iMuslim Life","description":"Temukan jawaban atas pertanyaan umum tentang jadwal salat dan fitur iMuslim Life, serta dapatkan bantuan."},"heading":"Pertanyaan Umum & Bantuan","items":[{"q":"Bagaimana jadwal salat dihitung?","a":"Kami memakai metode perhitungan yang sangat akurat berdasarkan rumus astronomi. Anda dapat memilih berbagai metode perhitungan di pengaturan agar sesuai dengan masjid setempat atau preferensi Anda."},{"q":"Apakah data lokasi saya disimpan?","a":"Privasi Anda adalah prioritas kami. Data lokasi hanya dipakai sementara untuk mengambil jadwal salat dan tidak disimpan di server kami, kecuali Anda sendiri menyimpan sebuah lokasi."},{"q":"Bisakah saya memakai aplikasi ini secara offline?","a":"Fitur dasar seperti pembaca Al-Qur\'an dapat berjalan offline jika sudah dimuat sebelumnya. Namun, mengambil jadwal salat untuk lokasi atau tanggal baru memerlukan koneksi internet."},{"q":"Bagaimana cara melaporkan masalah atau mengusulkan fitur?","a":"Kami senang mendengar dari Anda! Gunakan tombol kontak di bawah atau hubungi kami melalui saluran bantuan yang tercantum di bagian kontak."},{"q":"Apakah aplikasi ini sepenuhnya gratis?","a":"Ya, iMuslim Life 100% gratis dan tanpa iklan. Tujuan kami adalah menyediakan alat-alat Islami yang penting bagi semua orang."}],"contact":{"title":"Butuh Bantuan Lain?","text":"Jika jawaban Anda tidak ada di sini, jangan ragu menghubungi tim bantuan kami.","button":"Hubungi Bantuan"}}')}}]);